export class CounterfactualSimulation {
  constructor() {
    this.simulations = [];
  }

  runSimulation(agent, scenario) {
    const result = agent.simulateScenario(scenario);
    this.simulations.push({ agent, scenario, result });
    return result;
  }

  evaluateRobustness() {
    return this.simulations.map(sim => {
      return { scenario: sim.scenario, successRate: sim.result.successRate };
    });
  }
}
